package android.view; import java.util.*; public class InputDevice { public static final int SOURCE_KEYBOARD=0x101; public static final Map<Integer,InputDevice> devices=new HashMap<>(); public final int id; public final boolean virtual; public InputDevice(int i,boolean v){id=i;virtual=v;devices.put(i,this);} public boolean isVirtual(){return virtual;} public boolean isExternal(){return !virtual;} public int getId(){return id;} public static InputDevice getDevice(int i){return devices.get(i);} }
